    /// The string name of an event (W3C SCXML 3.12).
    public func getEventName(_ event: StaticUnionEvent) -> String {
        switch event {
        case .boardRead:
            return "board.read"
        case .errorExecution:
            return "error.execution"
        case .shapeBoarded:
            return "shape.boarded"
        case .shapeHeld:
            return "shape.held"
        case .shapeSaid:
            return "shape.said"
        case .shapesGrouped:
            return "shapes.grouped"
        case .shapesPicked:
            return "shapes.picked"
        case .shapesRowed:
            return "shapes.rowed"
        case .shapesSent:
            return "shapes.sent"
        case .null:
            return ""
        }
    }

